#include <bits/stdc++.h>
using namespace std;
#define int long long
int n, m, k;
char s[1010][1010];
char c[20];
bool vis[1010][1010];
int d[1010][1010];
int dx[] = {1, -1, 0, 0};
int dy[] = {0, 0, 1, -1};
vector <pair <int, int>> place;
int tot = 0;
inline bool calc (int x, int y) {
    if (1 <= x && x <= n && 1 <= y && y <= m)
        return true;
    return false;
}
inline void bfs (int x, int y) {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            vis[i][j] = false;
    queue <pair <int, int>> p;
    p.push ({x, y});
    vis[x][y] = true;
    d[x][y] = 0;
    while (!p.empty()) {
        pair <int, int> cur = p.front();
        p.pop();
        for (int t = 0; t <= 3; t++) {
            int nx = cur.first + dx[t], ny = cur.second + dy[t];
            if (calc (nx, ny) && vis[nx][ny] == false && s[nx][ny] != '#') {
                d[nx][ny] = d[cur.first][cur.second] + 1;
                p.push (nx, ny);
            }
        }
    }
}
signed main () {
    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    //freopen ("bot.in", "r", stdin);
    //freopen ("bot.out", "w", stdout);
    cin >> n >> m >> k;
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            cin >> s[i][j];
    for (int i = 1; i <= k; i++)
        cin >> c[i];
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (s[i][j] == 'S') {
                place.push_back ({i, j});
    for (int l = 1; l <= k; l++)
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
                if (s[i][j] == c[l])
                    place.push_back({i, j});
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= m; j++)
            if (s[i][j] == 'T') {
                place.push_back ({i, j});
    int len = place.size();
    for (int i = 1; i < len; i++) {
        int x = place[i - 1].first, y = place[i - 1].second;
        bfs (x, y);
        int xs = place[i].first, ys = place[i].second;
        int dis = d[xs][ys];
        tot += dis;
    }
    cout << tot << '\n';
    return 0;
}

