#include <bits/stdc++.h>
using namespace std;
#define int long long
int n, m, K;
string s, t;
int dp[1010][1010][20][2];
signed main () {
    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    //freopen ("rec.in", "r", stdin);
    //freopen ("rec.out", "w", stdout);
    cin >> n >> m >> K;
    cin >> s >> t;
    s = " " + s, t = " " + t;
    memset (dp, 128, sizeof (dp));
    dp[0][0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            for (int k = 0; k <= K; k++) {
                for (int d = 0; d <= 1; d++) {
                    if (d == 0) {
                        dp[i][j][k][d] = max ({dp[i - 1][j][k][0],
                        dp[i][j - 1][k][0], dp[i - 1][j - 1][k][0],
                         dp[i - 1][j][k][1], dp[i][j - 1][k][1],
                          dp[i - 1][j - 1][k][1]});
                    }
                    else {
                        if (s[i] == t[j]) {
                            if (k != 0) {
                                dp[i][j][k][d] = max (dp[i - 1][j - 1][k - 1][0], dp[i - 1][j - 1][k][1]) + 1;
                            }
                        }
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int k = 0; k <= K; k++)
        for (int d = 0; d <= 1; d++)
            ans = max (ans, dp[n][m][k][d]);
    cout << ans << '\n';
    return 0;
}

