#include <bits/stdc++.h>
using namespace std;
#define int long long
int n;
int d[510];
const int P = 998244353;
int l[510], r[510];
int tot = 0;
int ok = 0;
inline int qpow (int a, int b) {
    int ans = 1;
    int base = a;
    while (b != 0) {
        if (b % 2 == 1)
            ans = (ans * base) % P;
        base = (base * base) % P;
        b /= 2;
    }
    return ans;
}
inline void dfs (int k) {
    if (k == n + 1) {
        tot++;
        for (int i = 1; i <= n; i++) {
            int v = i - 1;
            int cnt = 0;
            for (int j = 1; j <= n; j++) {
                if (l[j] <= v && v <= r[j])
                    cnt++;
            }
            if (cnt == i)
                ok++;
        }
        return;
    }
    for (int i = 0; i <= d[k]; i++) {
        for (int j = i; j <= d[k]; j++) {
            l[k] = i, r[k] = j;
            dfs (k + 1);
        }
    }
}
