using namespace std;
#define int long long
int n;
int p[1000010];
int q;
inline int phi (int x) {
    if (x == 1)
        return 1;
    int ans = x;
    for (int i = 2; i * i <= x; i++) {
        if (x % i == 0) {
            ans = (ans * (i - 1)) / i;
            while (x % i == 0)
                x /= i;
        }
    }
    if (x > 1)
        ans = (ans * (x - 1)) / x;
    return ans;
}
