    while (q--) {
        int l, r;
        cin >> l >> r;
        int ans = 0;
        for (int i = l; i <= r; i++) {
            for (int j = i + 1; j <= r; j++) {
                int tot = p[i] * p[j];
                ans = max (ans, phi (tot));
            }
        }
        cout << ans << '\n';
    }
    return 0;
}

