#include <bits/stdc++.h>
using namespace std;
#define int long long
int n;
int a[1000010];
int ans = 0;
int x[1000010];
signed main () {
    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    freopen ("wowo.in", "r", stdin);
    freopen ("wowo.out", "w", stdout);
    cin >> n;
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    x[0] = a[1] - 1, x[n] = a[n] - 1;
    for (int i = 1; i <= n - 1; i++)
        x[i] = min (a[i], a[i + 1]) - 1;
    for (int i = 1; i <= n; i++) {
        int l = x[i - 1], r = x[i];
        x[i] -= max ((l + r - (a[i] - 1)), 0LL);
    }
    for (int i = 0; i <= n; i++)
        ans += x[i];
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long
int T;
int a[1000010];
int u[1000010];
int x[1000010], t[1000010];
double lst[1000010];
inline void solve () {
    int n, m, l, tend;
    cin >> n >> m >> l >> tend;
    a[0] = 0, a[n] = l;
    for (int i = 1; i <= n - 1; i++)
        cin >> a[i];
    for (int i = 1; i <= n; i++)
        cin >> u[i];
    for (int i = 1; i <= m; i++)
        cin >> x[i] >> t[i];
    for (int i = 1; i <= n; i++) {
        int time = a[i] - a[i - 1];
        double need = 1.0 * time / u[i];
        lst[i] = lst[i - 1] + need;
    }
    if (1.0 * tend < lst[n]) {
        cout << -1 << '\n';
        return;
    }
    int fail = 0;
    for (int i = 1; i <= n; i++) {
        double speed = 1.0 * l / tend;
        double work = speed * t[i];
        if (1.0 * x[i] != work)
            fail++;
    }
    cout << fail << '\n';
}
signed main () {
    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    freopen ("WOWO.in", "r", stdin);
    freopen ("WOWO.out", "w", stdout);
    cin >> T;
    while (T--)
        solve ();
    return 0;
}

