#include <bits/stdc++.h>
using namespace std;
#define int long long
int n;
int f[1000010];
int a[1000010];
priority_queue <int> p[1000010];
vector <int> e[1000010];
int ans1 = 0;
signed main () {
    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    //freopen (".in", "r", stdin);
    //freopen (".out", "w", stdout);
    cin >> n;
    for (int i = 2; i <= n; i++)
        cin >> f[i];
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    for (int i = 2; i <= n; i++)
        if (a[i] > 0)
            p[f[i]].push(a[i]);
    if (a[1] > 0)
        ans1 += a[1];
    int ma = 0;
    for (int i = 1; i <= n; i++) {
        if (p[i].size() == 0)
            continue;
        else if (p[i].size() == 1)
            e[i].push_back (p[i].top());
        else {
            int top1 = p[i].top();
            p[i].pop();
            int top2 = p[i].top();
            e[i].push_back (top1);
            ma = max (ma, top2);
        }
    }
    for (int i = 1; i <= n; i++) {
        if (!e[i].empty())
            ans += e[i][0];
    }
    ans += ma;
    cout << ans << '\n';
    return 0;
}

