inline void dfs (int l, int r) {
    if (l >= r)
        return;
    int mid = (l + r) / 2;
    dfs (l, mid);
    dfs (mid + 1, r);
    int p1 = l, p2 = mid + 1;
    int it = 0;
    while (p1 <= mid && p2 <= r) {
        if (a[p1].first <= a[p2].first)
            b[++it] = a[p1++];
        else
            b[++it] = a[p2++];
    }
    while (p1 <= mid)
        b[++it] = a[p1++];
    while (p2 <= r)
        b[++it] = a[p2++];
    for (int i = 1; i <= r - l + 1; i++)
        a[l + i - 1] = b[i];
}
