using namespace std;
#define int long long
int n, r;
int a[1000010], c[1000010];
int lst[1000010];
bool f[1000010];
set <int> st;
int tot = 0;
signed main () {
    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    //freopen ("zerofree.in", "r", stdin);
    //freopen ("zerofree.out", "w", stdout);
    cin >> n >> r;
    for (int i = 1; i <= n; i++)
        cin >> a[i];
    for (int i = 1; i <= n; i++)
        cin >> c[i];
    for (int i = 1; i <= n; i++)
        lst[i] = (lst[i - 1] + a[i]) % r;
    f[0] = true;
    for (int i = 1; i <= n; i++)
        f[i] = (f[i - 1] & (lst[i] == 0));
    if (f[n] == true) {
        cout << 0 << '\n';
        return 0;
    }
    bool meet = false;
    int mi = 1e9 + 18;
    for (int i = n; i >= 1; i--) {
            mi = min (mi, c[i]);
        if (lst[i] == 0) {
            meet = true;
            continue;
        }
        int x1 = -lst[i];
        int x2;
        if (lst[i] < 0)
            x2 = lst[i] + 7;
        else
            x2 = 7 - lst[i];
        st.insert (x1);
        st.insert (x2);
        if ((int)st.size () >= 2 * r - 2) {
            if (f[i] == true || meet == true) {
                tot += mi;
                mi = 1e9 + 18;
                st.clear();
                meet = false;
            }
        }
    }
    cout << tot << '\n';
    return 0;
}

