inline void solve () {
    int n, m;
    cin >> n >> m;
    for (int i = 1; i <= m; i++) {
        int x, y;
        cin >> x >> y;
        e[x].push_back (y);
        e[y].push_back (x);
    }
    priority_queue <pair <int, int>> p;
    int c = 0;
    d[1] = 0;
    for (int i = 2; i <= n; i++)
        d[i] = 2e18;
    p.push ({0, 1});
    while (!p.empty ()) {
        pair <int, int> cur = p.top();
        p.pop();
        int u = cur.second, v = cur.first;
        if (v != d[u])
            continue;
        c++;
        for (auto y : e[u]) {
            if (d[v] > d[u] + 1) {
                d[v] = d[u] + 1;
                p.push ({d[v], v});
            }
        }
    }
    cout << c << '\n';
}
