        if (v != d[u])
            continue;
        c++;
        for (auto y : e[u]) {
            if (d[y] > d[u] + 1) {
                d[y] = d[u] + 1;
                p.push ({d[y], -y});
            }
        }
    }
    cout << c << '\n';
    for (int i = 1; i <= n; i++)
        e[i].clear();
}
