    ios::sync_with_stdio (false);
    cin.tie (0);
    cout.tie (0);
    //freopen ("path.in", "r", stdin);
    //freopen ("path.out", "w", stdout);
    cin >> C >> T;
    while (T--)
        solve ();
    return 0;
}
